(() => {
  const $ = (s, root=document) => root.querySelector(s);
  const api = async (path, options={}) => { const r = await fetch(path, {headers:{'Content-Type':'application/json'}, ...options}); const data = await r.json().catch(()=>({})); if(!r.ok) throw new Error(data?.error?.message || `请求失败 ${r.status}`); return data; };
  const state = {view:'overview', run:null, schema:null, workflow:null, timer:null, preflight:null};
  const titles = {overview:'概览',run:'开始运行',resources:'资源管理',accounts:'已创建账户',history:'运行记录',settings:'配置中心'};
  function toast(msg, bad=false){const e=$('#toast'); e.textContent=msg; e.className=`toast ${bad?'bad':''}`; setTimeout(()=>e.classList.add('hidden'),3200)}
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function setView(name){state.view=name; document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name)); document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`)); $('#pageTitle').textContent=titles[name]; render(name)}
  async function boot(){try{await api('/api/health'); $('#healthText').textContent='本机服务已连接'; $('#healthText').previousElementSibling.style.background='#74c787';}catch(e){$('#healthText').textContent='服务未连接';} document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view)); $('#refreshBtn').onclick=()=>render(state.view); await loadSchema(); await loadWorkflow(); setView('overview'); poll();}
  async function loadSchema(){try{state.schema=await api('/api/run-parameters/schema')}catch(e){state.schema=null}}
  async function loadWorkflow(){try{state.workflow=await api('/api/workflow/definition')}catch(e){state.workflow=null}}
  async function poll(){try{const current=await api('/api/runs/current'); state.run=current&&Object.keys(current).length?current:null; renderRunState();}catch(e){} clearTimeout(state.timer); state.timer=setTimeout(poll,2000)}
  function metric(label,value,cls=''){return `<div class="card"><div class="label">${label}</div><div class="metric ${cls}">${esc(value)}</div></div>`}
  async function renderOverview(){let email={},card={},accounts={}; try{[email,card,accounts]=await Promise.all([api('/api/resources/summary?type=email'),api('/api/resources/summary?type=card'),api('/api/registered-accounts/summary')])}catch(e){} const run=state.run; $('#view-overview').innerHTML=`<div class="grid grid-4">${metric('可用邮箱',email.available??'-')} ${metric('可用卡片',card.available??'-')} ${metric('READY 账户',accounts.ready??accounts.available??'-')} ${metric('当前运行',run?.status||'空闲')}</div><div class="grid grid-2" style="margin-top:18px"><div class="card"><h2>当前任务</h2>${run?runCard(run):'<div class="empty">当前没有运行中的任务。<br><button class="primary" style="margin-top:12px" onclick="window.__gotoRun()">开始一次运行</button></div>'}</div><div class="card"><h2>快速入口</h2><div class="grid grid-2"><button class="ghost" onclick="window.__gotoRun()">创建账号</button><button class="ghost" onclick="window.__gotoResources()">管理邮箱/卡片</button><button class="ghost" onclick="window.__gotoAccounts()">查看 READY 账户</button><button class="ghost" onclick="window.__gotoSettings()">检查运行配置</button></div><p class="help" style="margin-top:16px">所有真实运行都先经过预检；支付和不可逆操作会停在人工确认点。</p></div></div>`}
  function runCard(r){return `<div class="section-head"><span class="status ${esc(r.status)}">${esc(r.status)}</span><span class="muted">${esc(r.current_step_id||'')}</span></div><p>${esc(r.current_action||r.waiting_reason||'工作流运行中')}</p><div class="label">账户 ${r.account_index||0} · 浏览器 ${esc(r.browser_state||'-')}</div>${r.last_error?`<div class="danger-note" style="margin-top:12px">${esc(r.last_error)}</div>`:''}`}
  async function renderRun(){if(!state.schema) await loadSchema(); if(!state.workflow) await loadWorkflow(); const fields=(state.schema?.groups||[]).flatMap(g=>g.fields||[]); const field=(key)=>fields.find(f=>f.key===key)||{}; const select=(key)=>{const f=field(key); return `<div class="field"><label>${esc(f.label||key)}</label><select id="p-${key}">${(f.options||[]).map(o=>`<option value="${esc(o)}" ${o===f.default?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}; $('#view-run').innerHTML=`<div class="run-layout"><div><div class="card"><h2>新建运行</h2><p class="muted">按操作者习惯分成“任务、策略、数量”三步。提交后会先做资源、浏览器和网络预检。</p><div class="form-grid">${select('task_type')}${select('mode')}${select('interaction')}${select('network')}<div class="field"><label>目标数量</label><input id="p-target_count" type="number" min="1" max="100" value="1"></div><div class="field"><label>浏览器后端</label><select id="p-browser_backend"><option value="cloak">CloakBrowser（推荐）</option><option value="firefox_private">Firefox 隐私模式</option></select></div><div class="field" id="accountIdsField"><label>READY 账户 ID（开通会员时）</label><input id="p-account_ids" placeholder="多个 ID 用逗号分隔"></div><div class="field" id="checkoutGoalField"><label>开通目标</label><select id="p-checkout_goal"><option value="complete">完整开通（含支付）</option><option value="pricing_page">仅验证套餐页</option></select></div></div><div class="danger-note" style="margin-top:16px">真实运行会操作浏览器并可能访问第三方服务。支付、取消订阅和未知副作用步骤会保留人工确认。</div><div class="actions"><button class="primary" id="preflightBtn">预检并开始</button></div></div><div class="card" style="margin-top:18px"><h2>流程阶段</h2><div class="workflow">${(state.workflow?.phases||[]).map(p=>`<div class="phase"><strong>${esc(p.title)}</strong><small>${esc(p.description)}</small></div>`).join('')}</div></div></div><div id="runSide"></div></div>`; $('#p-task_type').onchange=()=>{const checkout=$('#p-task_type').value==='checkout'; $('#accountIdsField').style.display=checkout?'block':'none'; $('#checkoutGoalField').style.display=checkout?'block':'none';}; $('#p-task_type').dispatchEvent(new Event('change')); $('#preflightBtn').onclick=startRun; renderRunSide();}
  async function startRun(){const val=id=>$('#p-'+id)?.value||''; const p={execution_mode:'production',mode:val('mode'),interaction:val('interaction'),network:val('network'),target_count:val('target_count'),task_type:val('task_type'),account_ids:val('account_ids'),checkout_goal:val('checkout_goal'),browser_backend:val('browser_backend')}; const btn=$('#preflightBtn'); btn.disabled=true; btn.textContent='预检中…'; try{const check=await api('/api/runs/preflight',{method:'POST',body:JSON.stringify(p)}); renderChecks(check); if(!check.ok){toast('预检未通过，请处理阻塞项',true); return} const run=await api('/api/runs',{method:'POST',body:JSON.stringify(p)}); state.run=run; toast('任务已启动'); renderRunSide();}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent='预检并开始'} }
  function renderChecks(c){state.preflight=c; const side=$('#runSide'); if(!side)return; side.innerHTML=`<div class="card"><h2>预检结果</h2><ul class="check-list">${(c.checks||[]).map(x=>`<li><span>${esc(x.label)}<small class="muted" style="display:block">${esc(x.detail)}</small></span><span class="status ${x.status==='ready'?'ready':'error'}">${x.status==='ready'?'通过':'阻塞'}</span></li>`).join('')}</ul></div>`}
  function renderRunSide(){const side=$('#runSide');if(!side)return; if(!state.run){side.innerHTML=state.preflight?`<div class="card"><h2>预检结果</h2><ul class="check-list">${(state.preflight.checks||[]).map(x=>`<li><span>${esc(x.label)}<small class="muted" style="display:block">${esc(x.detail)}</small></span><span class="status ${x.status==='ready'?'ready':'error'}">${x.status==='ready'?'通过':'阻塞'}</span></li>`).join('')}</ul></div>`:'<div class="card"><h2>运行状态</h2><div class="empty">提交预检后，实时状态会显示在这里。</div></div>';return} const req=state.run.operator_request; const decisionButtons=(req?.allowed_decisions||[]).map(d=>`<button class="${/stripe|payment|cancel/i.test(d)?'danger':'primary'} small-btn" onclick="window.__decision('${esc(d)}')">${esc({verify_manual:'已完成，请验证',advance_after_manual:'继续下一步',retry_auto:'重试自动步骤',skip_account:'跳过账户',defer_account:'稍后处理',abort_batch:'终止批次',keep_open:'保持浏览器打开',restart_browser:'重启浏览器'}[d]||d)}</button>`).join(''); side.innerHTML=`<div class="card">${runCard(state.run)}<div class="actions"><button class="danger" onclick="window.__stopRun()">安全停止</button><button class="ghost" onclick="window.__forceStop()">强制结束</button></div></div>${req?`<div class="card operator" style="margin-top:18px"><h3>${esc(req.title||'需要人工处理')}</h3><p>${esc(req.instruction||req.description||'请在浏览器中完成当前操作')}</p><div class="help">${esc(req.after_action||'完成后选择下方操作，系统将重新验证页面状态。')}</div><div class="actions" style="justify-content:flex-start;flex-wrap:wrap">${decisionButtons}</div></div>`:''}<div class="card" style="margin-top:18px"><h2>实时事件</h2><div class="event-log">${(state.run.events||[]).map(e=>`<div>[${esc(e.level)}] ${esc(e.message)}</div>`).join('')}</div></div>`;}
  function renderRunState(){if(state.view==='overview')renderOverview();if(state.view==='run')renderRunSide();}
  async function decision(d){try{state.run=await api('/api/runs/decisions',{method:'POST',body:JSON.stringify({decision:d})});renderRunSide();}catch(e){toast(e.message,true)}}
  window.__decision=decision;
  async function renderResources(){let type='email'; let data={}; try{data=await api('/api/resources?type='+type)}catch(e){} $('#view-resources').innerHTML=`<div class="grid grid-2"><div class="card"><h2>邮箱资源</h2><p class="muted">OAuth token 只用于本机工作流，列表仅显示掩码。</p><div class="table-wrap"><table class="table"><thead><tr><th>资源</th><th>状态</th><th>更新时间</th></tr></thead><tbody>${(data.items||[]).map(x=>`<tr><td>${esc(x.display)}</td><td><span class="status ${esc(x.state)}">${esc(x.state)}</span></td><td>${esc(x.updated_at||'-')}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">暂无邮箱</td></tr>'}</tbody></table></div></div><div class="card"><h2>添加邮箱</h2><form id="emailForm" class="form-grid"><div class="field full"><label>邮箱</label><input name="email" type="email" required></div><div class="field"><label>邮箱密码</label><input name="password" type="password" required></div><div class="field"><label>Client ID</label><input name="client_id" required></div><div class="field full"><label>Refresh Token</label><textarea name="refresh_token" required></textarea></div><div class="actions full"><button class="primary">加入资源池</button></div></form><p class="help">新增的敏感字段不会回显到普通日志。</p></div></div><div class="section-head"><h2>卡片资源</h2><button class="ghost" onclick="window.__loadCards()">刷新卡片</button></div><div id="cardsBox" class="card"><div class="empty">点击刷新加载卡片摘要。</div></div>`; $('#emailForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{await api('/api/resources/emails',{method:'POST',body:JSON.stringify(body)});toast('邮箱已加入资源池');renderResources()}catch(x){toast(x.message,true)}}}
  window.__loadCards=async()=>{try{const d=await api('/api/resources?type=card');$('#cardsBox').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>卡片</th><th>状态</th><th>更新时间</th></tr></thead><tbody>${(d.items||[]).map(x=>`<tr><td>${esc(x.display)}</td><td><span class="status ${esc(x.state)}">${esc(x.state)}</span></td><td>${esc(x.updated_at||'-')}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">暂无卡片</td></tr>'}</tbody></table></div>`}catch(e){toast(e.message,true)}};
  async function renderAccounts(){let d={};try{d=await api('/api/registered-accounts')}catch(e){}$('#view-accounts').innerHTML=`<div class="card"><div class="section-head"><h2>账户库存</h2><span class="muted">凭据始终保存在本机加密存储</span></div><div class="table-wrap"><table class="table"><thead><tr><th>账户</th><th>状态</th><th>优惠状态</th><th>后端</th><th>更新时间</th></tr></thead><tbody>${(d.items||[]).map(x=>`<tr><td>${esc(x.email||x.display||'-')}</td><td><span class="status ${esc(x.status)}">${esc(x.status)}</span></td><td>${esc(x.offer_status||'-')}</td><td>${esc(x.browser_backend||'-')}</td><td>${esc(x.updated_at||'-')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无已创建账户</td></tr>'}</tbody></table></div></div>`}
  async function renderHistory(){let d={};try{d=await api('/api/history')}catch(e){}$('#view-history').innerHTML=`<div class="card"><h2>运行记录</h2><div class="table-wrap"><table class="table"><thead><tr><th>Session</th><th>阶段</th><th>状态</th><th>错误</th><th>更新时间</th></tr></thead><tbody>${(d.items||[]).map(x=>`<tr><td>${esc(x.session_id)}</td><td>${esc(x.stage)}</td><td><span class="status ${esc(x.status)}">${esc(x.status)}</span></td><td>${esc(x.last_error||'-')}</td><td>${esc(x.updated_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无运行记录</td></tr>'}</tbody></table></div></div>`}
  async function renderSettings(){let d={};try{d=await api('/api/settings')}catch(e){toast(e.message,true)}$('#view-settings').innerHTML=`<div class="card"><div class="section-head"><div><h2>运行配置</h2><p class="muted">保存后立即作用于下一次任务；密码和授权密钥只显示是否已配置。</p></div><button class="primary" id="saveSettings">保存配置</button></div><form id="settingsForm">${(d.items||[]).map(x=>`<div class="setting-row"><div class="setting-label"><strong>${esc(x.label)}</strong><small>${esc(x.key)}</small></div><div>${x.type==='boolean'?`<select name="${esc(x.key)}"><option value="true" ${x.value?'selected':''}>开启</option><option value="false" ${!x.value?'selected':''}>关闭</option></select>`:x.type==='select'?`<select name="${esc(x.key)}">${(x.options||[]).map(o=>`<option value="${esc(o)}" ${o===x.value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="${esc(x.key)}" type="${x.type==='password'?'password':x.type}" value="${x.secret?'':esc(x.value)}" placeholder="${x.secret&&x.configured?'已配置，留空保持不变':''}">`}</div><span class="label">${x.secret?(x.configured?'已配置':'未配置'):''}</span></div>`).join('')}</form></div>`;$('#saveSettings').onclick=async()=>{const body=Object.fromEntries(new FormData($('#settingsForm'))); Object.keys(body).forEach(k=>{if(body[k]==='' && ['IKUAI_PASSWORD','PROXY_PASSWORD','CLOAKBROWSER_LICENSE_KEY'].includes(k))delete body[k]});try{await api('/api/settings',{method:'PUT',body:JSON.stringify(body)});toast('配置已保存')}catch(e){toast(e.message,true)}}}
  async function render(name){if(name==='overview')return renderOverview();if(name==='run')return renderRun();if(name==='resources')return renderResources();if(name==='accounts')return renderAccounts();if(name==='history')return renderHistory();if(name==='settings')return renderSettings()}
  window.__gotoRun=()=>setView('run');window.__gotoResources=()=>setView('resources');window.__gotoAccounts=()=>setView('accounts');window.__gotoSettings=()=>setView('settings');window.__stopRun=async()=>{try{state.run=await api('/api/runs/stop',{method:'POST'});renderRunSide();toast('已请求安全停止')}catch(e){toast(e.message,true)}};window.__forceStop=async()=>{try{state.run=await api('/api/runs/force-stop',{method:'POST'});renderRunSide();toast('运行已强制结束')}catch(e){toast(e.message,true)}};
  boot();
})();
